userContent.text:
Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<div style="font-weight: bold; margin-bottom: 8px;">Parametric Space Curve</div>

<div style="display: flex; flex-direction: column; gap: 6px;">
  <label style="display: flex; align-items: center; gap: 4px;">
    <span style="display: inline-block; width: 35px; color: #333; font-weight: bold;">x(t) =</span>
    <input type="text" id="eq-x" value="4*cos(t)" style="flex-grow: 1; font-family: ui-monospace, monospace; padding: 4px;" />
  </label>
  <label style="display: flex; align-items: center; gap: 4px;">
    <span style="display: inline-block; width: 35px; color: #333; font-weight: bold;">y(t) =</span>
    <input type="text" id="eq-y" value="4*sin(t)" style="flex-grow: 1; font-family: ui-monospace, monospace; padding: 4px;" />
  </label>
  <label style="display: flex; align-items: center; gap: 4px;">
    <span style="display: inline-block; width: 35px; color: #333; font-weight: bold;">z(t) =</span>
    <input type="text" id="eq-z" value="t" style="flex-grow: 1; font-family: ui-monospace, monospace; padding: 4px;" />
  </label>
</div>

<div style="margin-top: 14px; display: flex; gap: 8px;">
  <button id="btn-play" style="flex: 1; font-weight: bold; padding: 6px;">Play</button>
  <button id="btn-view" style="flex: 1; padding: 6px;">Top View</button>
</div>

<label style="margin-top: 14px; font-weight: bold;">
  Parameter <i>t</i>: <span id="val-t" style="font-weight: normal; color: #0056b3;">0.00</span>
  <input type="range" id="t-slider" min="0" max="12.566" step="0.01" value="0" style="margin-top: 6px;" />
</label>

<div style="margin-top: 12px; background: #f8f9fa; padding: 8px 10px; border-radius: 4px; border: 1px solid #dee2e6; font-family: ui-monospace, monospace; font-size: 12px; display: grid; grid-template-columns: 1fr 1fr; gap: 4px;">
  <div style="grid-column: 1 / -1; font-weight: bold; color: #555; border-bottom: 1px solid #ccc; padding-bottom: 4px; margin-bottom: 2px;">Moving Point Position</div>
  <div>x: <span id="live-x">4.00</span></div>
  <div>y: <span id="live-y">0.00</span></div>
  <div>z: <span id="live-z">0.00</span></div>
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// axes -> LineSegments(BufferGeometry) dark grey
// axesArrows -> ConeGeometry(0.15, 0.4) dark grey
// ghost_helix -> plotParametric3D light gray, faint
// trace_helix -> plotParametric3D dark blue
// tracer -> SphereGeometry(0.2) red
// traceArrow -> ConeGeometry(0.25, 0.7) dark blue

const T_MAX = 4 * Math.PI; // Approx 12.566
let current_t = 0;
let isPlaying = false;

// Coordinates mapping:
// Math x -> Three Z
// Math y -> Three X
// Math z -> Three Y

/* ── 1. Axes and Ticks ── */
const axesMat = new THREE.LineBasicMaterial({ color: 0x333333 });
const axesGeo = new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(0, 0, -6), new THREE.Vector3(0, 0, 6.5), // Math x
  new THREE.Vector3(-6, 0, 0), new THREE.Vector3(6.5, 0, 0), // Math y
  new THREE.Vector3(0, 0, 0), new THREE.Vector3(0, 13.5, 0)  // Math z
]);
scene.add(new THREE.LineSegments(axesGeo, axesMat));

const arrowGeo = new THREE.ConeGeometry(0.15, 0.4, 8);
const arrowMat = new THREE.MeshBasicMaterial({ color: 0x333333 });

const arrowX = new THREE.Mesh(arrowGeo, arrowMat);
arrowX.position.set(0, 0, 6.5);
arrowX.rotation.x = Math.PI / 2; // points to +Z
scene.add(arrowX);

const arrowY = new THREE.Mesh(arrowGeo, arrowMat);
arrowY.position.set(6.5, 0, 0);
arrowY.rotation.z = -Math.PI / 2; // points to +X
scene.add(arrowY);

const arrowZ = new THREE.Mesh(arrowGeo, arrowMat);
arrowZ.position.set(0, 13.5, 0);
scene.add(arrowZ);

// Ticks
const tickSize = 0.2;
const tickPts = [];

// Math x (Three Z)
[-4, -2, 2, 4].forEach(v => {
  tickPts.push(new THREE.Vector3(-tickSize, 0, v), new THREE.Vector3(tickSize, 0, v));
  addLabel(v.toString(), new THREE.Vector3(tickSize + 0.4, 0, v));
});

// Math y (Three X)
[-4, -2, 2, 4].forEach(v => {
  tickPts.push(new THREE.Vector3(v, 0, -tickSize), new THREE.Vector3(v, 0, tickSize));
  addLabel(v.toString(), new THREE.Vector3(v, 0, tickSize + 0.4));
});

// Math z (Three Y)
[2, 4, 6, 8, 10, 12].forEach(v => {
  tickPts.push(new THREE.Vector3(-tickSize, v, 0), new THREE.Vector3(tickSize, v, 0));
  addLabel(v.toString(), new THREE.Vector3(-tickSize - 0.4, v, 0));
});

scene.add(new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(tickPts), axesMat));

// Axis labels
addLabel('<i>x</i>', new THREE.Vector3(0, 0, 7), { bold: true, fontSize: '15px' });
addLabel('<i>y</i>', new THREE.Vector3(7, 0, 0), { bold: true, fontSize: '15px' });
addLabel('<i>z</i>', new THREE.Vector3(0, 14, 0), { bold: true, fontSize: '15px' });
addLabel('<b>r</b>(<i>t</i>) = 4 cos <i>t</i> <b>i</b> + 4 sin <i>t</i> <b>j</b> + <i>t</i> <b>k</b>', new THREE.Vector3(0, 12.5, -3.5), { fontSize: '15px', color: '#111' });

/* ── 2. Parametric Plots ── */
const ghost_helix = plotParametric3D('ghost_helix', {
  x: '4*sin(t)',
  y: 't',
  z: '4*cos(t)',
  variables: ['t'],
  tDomain: [0, T_MAX],
  samples: 200,
  color: 0xa0a0a0
});
ghost_helix.object.material.transparent = true;
ghost_helix.object.material.opacity = 0.4;

const trace_helix = plotParametric3D('trace_helix', {
  x: '4*sin(t)',
  y: 't',
  z: '4*cos(t)',
  variables: ['t'],
  tDomain: [0, 0.001],
  samples: 200,
  color: 0x1f3b6c
});

/* ── 3. Tracer Elements ── */
const tracerMat = new THREE.MeshBasicMaterial({ color: 0xdc3545 });
const tracer = new THREE.Mesh(new THREE.SphereGeometry(0.2, 16, 16), tracerMat);
scene.add(tracer);

registerInteractive(tracer, {
  title: "Vector-Valued Function",
  body: "The tracer marks the tip of the position vector r(t) at the current parameter value t."
});

const traceArrowGeo = new THREE.ConeGeometry(0.25, 0.7, 8);
traceArrowGeo.rotateX(-Math.PI / 2); // Orient so tip is at local -Z
const traceArrow = new THREE.Mesh(traceArrowGeo, new THREE.MeshBasicMaterial({ color: 0x1f3b6c }));
scene.add(traceArrow);

/* ── 4. Interaction Logic ── */
function updatePoint() {
  const f_math_y = trace_helix.fx; // Three X
  const f_math_z = trace_helix.fy; // Three Y
  const f_math_x = trace_helix.fz; // Three Z

  let px, py, pz;
  try { px = f_math_x(current_t); } catch { px = NaN; }
  try { py = f_math_y(current_t); } catch { py = NaN; }
  try { pz = f_math_z(current_t); } catch { pz = NaN; }

  const valid = Number.isFinite(px) && Number.isFinite(py) && Number.isFinite(pz);

  if (valid) {
    tracer.position.set(py, pz, px);
    tracer.visible = true;

    let px1, py1, pz1;
    try {
      px1 = f_math_x(current_t + 1e-3);
      py1 = f_math_y(current_t + 1e-3);
      pz1 = f_math_z(current_t + 1e-3);
    } catch { px1 = NaN; }

    if (Number.isFinite(px1) && Number.isFinite(py1) && Number.isFinite(pz1)) {
      const dir = new THREE.Vector3(py1 - py, pz1 - pz, px1 - px);
      if (dir.lengthSq() > 1e-8) {
        traceArrow.position.set(py, pz, px);
        traceArrow.lookAt(py + dir.x, pz + dir.y, px + dir.z);
        traceArrow.visible = true;
      } else {
        traceArrow.visible = false;
      }
    } else {
      traceArrow.visible = false;
    }

    document.getElementById('live-x').textContent = px.toFixed(2);
    document.getElementById('live-y').textContent = py.toFixed(2);
    document.getElementById('live-z').textContent = pz.toFixed(2);
  } else {
    tracer.visible = false;
    traceArrow.visible = false;
    document.getElementById('live-x').textContent = 'NaN';
    document.getElementById('live-y').textContent = 'NaN';
    document.getElementById('live-z').textContent = 'NaN';
  }

  document.getElementById('val-t').textContent = current_t.toFixed(2);

  trace_helix.tDomain = [0, Math.max(1e-5, current_t)];
  trace_helix.sample();
}

// Bind equations. Note that bindEquationInput parses the expression, and if successful, calls setX/setY/setZ.
// Math x -> Three Z
bindEquationInput('eq-x', [
  { handle: ghost_helix, method: 'setZ' },
  { handle: trace_helix, method: 'setZ' }
], { variables: ['t'], onChange: () => { if (!isPlaying) updatePoint(); } });

// Math y -> Three X
bindEquationInput('eq-y', [
  { handle: ghost_helix, method: 'setX' },
  { handle: trace_helix, method: 'setX' }
], { variables: ['t'], onChange: () => { if (!isPlaying) updatePoint(); } });

// Math z -> Three Y
bindEquationInput('eq-z', [
  { handle: ghost_helix, method: 'setY' },
  { handle: trace_helix, method: 'setY' }
], { variables: ['t'], onChange: () => { if (!isPlaying) updatePoint(); } });

/* ── 5. Playback and Controls ── */
const slider = document.getElementById('t-slider');
const btnPlay = document.getElementById('btn-play');

slider.addEventListener('input', (e) => {
  current_t = parseFloat(e.target.value);
  isPlaying = false;
  updatePlayBtn();
  updatePoint();
});

function updatePlayBtn() {
  btnPlay.textContent = isPlaying ? 'Pause' : 'Play';
  btnPlay.classList.toggle('active', isPlaying);
}

btnPlay.addEventListener('click', () => {
  isPlaying = !isPlaying;
  if (isPlaying && current_t >= T_MAX - 0.02) {
    current_t = 0;
  }
  updatePlayBtn();
});

let isTopView = false;
const btnView = document.getElementById('btn-view');
btnView.addEventListener('click', () => {
  isTopView = !isTopView;
  if (isTopView) {
    // Camera looks down the Y axis. Math x (Three Z) points down, Math y (Three X) points right.
    setCameraView({ projection: 'orthographic', azimuthDeg: 0, elevationDeg: 90, heightFraction: 0.85 });
    btnView.textContent = '3D View';
    btnView.classList.add('active');
  } else {
    setCameraView({ projection: 'orthographic', axisScreenAngles: { x: 30, z: 30 }, heightFraction: 0.85 });
    btnView.textContent = 'Top View';
    btnView.classList.remove('active');
  }
});

let lastTime = performance.now();
function loop() {
  requestAnimationFrame(loop);
  const now = performance.now();
  const dt = (now - lastTime) / 1000;
  lastTime = now;

  if (isPlaying) {
    // ~5 seconds to trace the full 12.56 curve
    current_t += dt * (T_MAX / 5);
    if (current_t >= T_MAX) {
      current_t = T_MAX;
      isPlaying = false;
      updatePlayBtn();
    }
    slider.value = current_t.toString();
    updatePoint();
  }
}

// Initial setup
updatePoint();
setCameraView({ projection: 'orthographic', axisScreenAngles: { x: 30, z: 30 }, heightFraction: 0.85 });
loop();
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

